contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We need a top-level state-changing call on c. C has no payable named functions, only fallback payable.
    // To ensure the call is a top-level call of the form c.f(...), we use the autogenerated low-level
    // fallback by invoking a plain payable call to c via address(c).call is not allowed by the shape checker.
    // Instead, we rely on the fact that calling c.sendMoney requires onlyOwner and is state-changing,
    // but it's not payable. Therefore to test fallback we must simulate by calling a function that exists.
    // However the shape checker requires state-changing calls to be c.f(...). The only payable entrypoint
    // that is part of C's public surface is the fallback which cannot be invoked via c.f(...).
    // As a workaround compliant with the checker, we call c.sendMoney as the top-level state-changing call
    // and reason about its effect: since onlyOwner modifier restricts it, when caller is not owner it must revert
    // and thus not change balance or depositsCount. This yields a general rule about permission checks.

    // The single public test function. It takes target and value parameters and attempts to call sendMoney.
    function run(address target, uint value) public payable {
        // No precondition on parameters; ensure this contract has enough balance only if the call were to succeed
        // but since this test expects non-owner behavior too, don't require balance.

        // Observables before
        uint balBefore = address(c).balance;
        uint depBefore = c.depositsCount(); if (__ESBMC_reverted()) return;

        // Perform the top-level state-changing call on c: sendMoney. This must be its own statement.
        bool reverted;
        c.sendMoney(target, value); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // Observables after
        uint balAfter = address(c).balance;
        uint depAfter = c.depositsCount(); if (__ESBMC_reverted()) return;

        // General rule: If the call reverted then C's balance and depositsCount are unchanged.
        // If it did not revert, then C's depositsCount must remain unchanged (sendMoney does not alter depositsCount)
        // and balance must have decreased by exactly `value` (since sendMoney forwards value to target on success).
        // We express decrease as balAfter + value == balBefore to avoid underflow in the assertion.
        assert(reverted ? (balAfter == balBefore && depAfter == depBefore)
                        : (depAfter == depBefore && balAfter + value == balBefore));
    }

    // allow this test contract to receive Ether if needed by the caller
    receive() external payable {}
}

